// servant: a module-level function; the serviced object is duck-typed
export function moveTo(shape, position) { shape.position = position; }

// trait-object form (Object.assign onto the prototype) - use sparingly
const movable = { moveTo(position) { this.position = position; } };
Object.assign(Circle.prototype, movable);
new Circle().moveTo({ x: 3, y: 4 });   // shadows same-named prototype members
